// Normalize the payload sent by the Moonday admin dashboard
// (edge function: substack-approval).
const p = $json.body || $json;

if (!p || !p.substack_post || !String(p.substack_post).trim()) {
  throw new Error('Missing substack_post in payload');
}

const title = p.title || 'Moonday Transit';
const sign = p.zodiac_sign_tag || '';
const image = p.image_url || '';
const slug = p.slug || '';

const body = String(p.substack_post).trim();
const imageBlock = image ? `![${sign || title}](${image})\n\n` : '';

return [{
  json: {
    post_id: p.post_id || null,
    slug,
    title,
    sign,
    excerpt: p.excerpt || '',
    image_url: image,
    publish_at: p.publish_at || null,
    sent_at: p.sent_at || new Date().toISOString(),
    subject: `Substack ready: ${title}`,
    markdown: imageBlock + body,
    canonical: slug ? `https://moondaylive.com/blog/${slug}` : 'https://moondaylive.com/blog'
  }
}];
